import json
import os
import sys
import unified_planning as up
from unified_planning.io import PDDLReader, PDDLWriter
from unified_planning.shortcuts import OneshotPlanner
from unified_planning.engines import SequentialPlanValidator

# Disable credits
up.shortcuts.get_environment().credits_stream = None

def solve_tasks(config_file):
    if not os.path.exists(config_file):
        print(f"Error: {config_file} not found.")
        return

    with open(config_file, 'r') as f:
        try:
            tasks = json.load(f)
        except json.JSONDecodeError as e:
            print(f"Error decoding JSON: {e}")
            return

    for task in tasks:
        task_id = task.get('id', 'unknown')
        domain_path = task.get('domain')
        problem_path = task.get('problem')
        output_path = task.get('plan_output')

        if not domain_path or not problem_path or not output_path:
            print(f"Skipping task {task_id}: Missing domain, problem, or output path.")
            continue

        print(f"Processing task: {task_id}")

        try:
            # Load
            reader = PDDLReader()
            problem = reader.parse_problem(domain_path, problem_path)
        except Exception as e:
            print(f"Error parsing problem for {task_id}: {e}")
            continue

        # Solve
        plan = None
        try:
            with OneshotPlanner(name='pyperplan') as planner:
                result = planner.solve(problem)
                if result.status.name in ['SOLVED_SATISFICING', 'SOLVED_OPTIMALLY']:
                    plan = result.plan
                else:
                    print(f"No plan found for {task_id}. Status: {result.status.name}")
        except Exception as e:
            print(f"Error solving {task_id}: {e}")
            continue

        if plan:
            # Validate
            try:
                validator = SequentialPlanValidator()
                val_result = validator.validate(problem, plan)
                if val_result.status.name != 'VALID':
                    print(f"Plan validation failed for {task_id}")
                else:
                    print(f"Plan validated for {task_id}")
            except Exception as e:
                print(f"Error validating {task_id}: {e}")

            # Save
            try:
                # Ensure output directory exists
                out_dir = os.path.dirname(output_path)
                if out_dir and not os.path.exists(out_dir):
                    os.makedirs(out_dir)

                with open(output_path, 'w') as f:
                    for action in plan.actions:
                        f.write(str(action) + '\n')
                print(f"Plan saved to {output_path}")
            except Exception as e:
                print(f"Error saving plan for {task_id}: {e}")

if __name__ == "__main__":
    solve_tasks("problem.json")

